// from a small allowance (about 4 per 10 s); use them to update state and LEDs, not to
// send commands.
// State of other devices. group_read() asks all members of a group for a value. Each
// device that answers shows up as H2_EV_FOUND; report_here() then asks it to send its
// changes of a cluster to this switch from then on, so the lamps keep the switch informed
// whoever switches them. Nothing has to be bound on the hub. (lib/sync.h does all this.) Name the attributes of interest with watch() on H2_EV_BOOT (at
// most 4); each change then arrives as H2_EV_REPORT, only when the value differs from the
// last one delivered, and at most every 250 ms per device and attribute. Treat a report
// as news about the state: update variables and LEDs. Radio messages sent while handling
// one come from the same small allowance as for H2_EV_VAR.
// Send any ZCL command. dest is H2_TO_GROUP(group) or H2_TO_DEVICE(n) for a device that
// has reported here (n as in H2_SRC_REMOTE(n)). Add H2_ZCL_GENERAL to the command for the
// general commands every cluster has (0x00 read attributes, 0x06 configure reporting, ...);
// without it the command is one of the cluster's own, as with zcl_group().
#define H2_TO_GROUP(g)     (g)
#define H2_TO_DEVICE(n)    (0x10000 + (n))
#define H2_ZCL_GENERAL     0x100
H2_FN(17, long, zcl_send,     long dest, long cluster, long command, const void *payload, long len);

H2_FN(15, long, watch,        long cluster, long attr);
H2_FN(18, long, report_here,  long device, long cluster);             // device n as in H2_SRC_REMOTE(n)
H2_FN(16, long, group_read,   long group, long cluster, long attr);

H2_FN(14, long, var_public,   long mask);                              // bit n = variable n is public
H2_FN( 1, long, relay_set,    long gang, long mode);                  // H2_OFF / H2_ON / H2_TOGGLE
H2_FN( 2, long, relay_get,    long gang);                             // 1 if on
H2_FN( 3, long, level_set,    long gang, long level);                 // dimmer output level 1..254
H2_FN( 4, long, scene_recall, long group, long scene);                // Recall Scene to a group
H2_FN( 5, long, zcl_group,    long group, long cluster, long command, const void *payload, long len);
H2_FN( 6, long, led_set,      long led, long red, long blue);         // 0..255 each; LED becomes manual
H2_FN( 7, long, led_release,  long led);                              // back to the normal indicator
H2_FN( 8, long, var_get,      long index);                            // 16 variables, zero at boot
H2_FN( 9, long, var_set,      long index, long value);
H2_FN(10, long, timer_start,  long id, long milliseconds);            // H2_EV_TIMER later; restarts if running
H2_FN(11, long, timer_stop,   long id);
H2_FN(12, long, log_value,    long tag, long value);                  // debug print on the bench console
// Multi-click detection for a button; call it on H2_EV_BOOT. clicks = 1 (default), 2 or 3.
//   wait = H2_CLICKS_INSTANT  every click is reported at once: SINGLE, then DOUBLE for a
//                             second click within 300 ms, then TRIPLE. Nothing is delayed,
//                             but a DOUBLE always follows a SINGLE.
//   wait = H2_CLICKS_WAIT     one event per gesture, 300 ms after the last click. A DOUBLE
//                             arrives alone, but a SINGLE is delayed by 300 ms.
#define H2_CLICKS_INSTANT  0
#define H2_CLICKS_WAIT     1
H2_FN(13, long, max_clicks,   long button, long clicks, long wait);
// How long a press is held before it counts as HOLD, and how long a second click may
// follow for DOUBLE, in milliseconds (hold 150..3000, double 100..1000; 0 = the default,
// 300 each). For all buttons; back to the defaults when the program is replaced. The
// hold time also applies to the long press that starts joining while off the network.
H2_FN(19, long, press_times,  long hold_ms, long double_ms);

int on_event(struct h2_event *ev);

#endif // H2_RULES_H

lib/each.h:
// Sending a command to lamps one by one instead of to their group.
//
// A group message is a broadcast: nobody acknowledges it, and copies of it stay on the
// air for a second or so, so on quick presses a lamp can take an old copy after a newer
// command (RESEARCH.md, 2026-11-24). A message to one device is acknowledged, retried only
// if it was not, and cannot overtake a newer one.
//
// The program keeps, in a variable of its choice, one bit per device it has heard from
// (devices are numbered 0..7 in the order they were first heard: H2_SRC_REMOTE(n)).
#ifndef H2_LIB_EACH_H
#define H2_LIB_EACH_H

#include "../h2_rules.h"

// Call for every event: records devices as they appear and forgets them when they are lost.
static __attribute__((noinline)) void each_track(struct h2_event *ev, long var_mask)
{
  if (!H2_IS_REMOTE(ev->source)) return;
  long bit = 1 << (ev->source - H2_SRC_REMOTE(0));
  long mask = var_get(var_mask);
  var_set(var_mask, ev->type == H2_EV_LOST ? (mask & ~bit) : (mask | bit));
}

// Send a cluster command to every device in the mask. Returns how many it was handed over
// for (a message refused by a limit does not count), so the caller can fall back to the
// group while nobody has been heard yet.
static __attribute__((noinline)) long each_send(long mask, long cluster, long command,
                                                const void *payload, long len)
{
  long sent = 0;
  for (long n = 0; n < 8; n++) {
    if (!(mask & (1 << n))) continue;
    if (zcl_send(H2_TO_DEVICE(n), cluster, command, payload, len) == 0) sent++;
  }
  return sent;
}

#endif

